  import http.server, os
  # Response cache: hold up to CACHE_MB MiB of warmed entries so repeat
  # traffic is served without recomputation. Each authorized request adds
  # one 2 MiB entry, filled with non-zero bytes so the memory is resident,
  # until the cache holds CACHE_MB worth.
  CACHE_MB = int(os.environ.get("CACHE_MB", "0"))
  ENTRY = 2 * 1024 * 1024
  cache = []
  class H(http.server.BaseHTTPRequestHandler):
      def do_GET(self):
          if self.path == "/healthz":
              return self.reply(200, "ok")
          token = open("/etc/shop-token/token").read().strip()
          if self.headers.get("Authorization") != "Bearer " + token:
              return self.reply(401, "bad token")
          if len(cache) * ENTRY < CACHE_MB * 1024 * 1024:
              cache.append(b"\xff" * ENTRY)
          self.reply(200, "hello from api")
      def reply(self, code, text):
          self.send_response(code); self.end_headers(); self.wfile.write(text.encode())
      def log_message(self, *a): pass
  http.server.ThreadingHTTPServer(("", 8080), H).serve_forever()

